/* @lc app=leetcode id=3558 lang=kotlin */ class Solution { fun assignEdgeWeights(edges: Array<IntArray>): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> HashSet<Int>().also { it.add(1) }.let { seen -> generateSequence(listOf(1)) { f -> f.flatMap { g[it].orEmpty() }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.count().let { D -> java.math.BigInteger.valueOf(2).modPow(java.math.BigInteger.valueOf(D - 2L), java.math.BigInteger.valueOf(1_000_000_007L)).toInt() } } } }